import random

# Symbolic constant to replace magic numbers
TOTAL_CARD_COUNT = 4
MIN_CARD_VALUE = 1
MAX_CARD_VALUE = 9
TARGET_SCORE = 24
SKIP_KEYWORD = 'pass'
DEFAULT_STATUS = False
SUCCESS_STATUS = True

class TwentyFourPointGame:
    def __init__(self) -> None:
        # Encapsulate Field: Change public attribute to private
        self._nums = []

    def _generate_cards(self):
        for i in range(TOTAL_CARD_COUNT):
            self._nums.append(random.randint(MIN_CARD_VALUE, MAX_CARD_VALUE))
        assert len(self._nums) == TOTAL_CARD_COUNT

    def get_my_cards(self):
        self._nums = []
        self._generate_cards()
        return self._nums.copy()  # Encapsulate Collection: Return a copy

    def answer(self, expression):
        # Introduce Explaining Variable / Replace Nested Conditional with Guard Clauses
        if expression == SKIP_KEYWORD:
            return self.get_my_cards()

        # Extract Method: Move digit counting logic
        digit_usage = self._count_digits_in_expression(expression)

        # Extract Method: Move validation logic
        if not self._has_valid_card_usage(digit_usage):
            return DEFAULT_STATUS

        # Extract Method: Simplify evaluation
        return self.evaluate_expression(expression)

    def _count_digits_in_expression(self, expression):
        # Refactored logic from answer()
        statistic = {}
        for c in expression:
            if c.isdigit() and int(c) in self._nums:
                statistic[c] = statistic.get(c, 0) + 1
        return statistic

    def _has_valid_card_usage(self, digit_usage):
        # Split Temporary Variable / Extract Method
        remaining_cards = {str(num): 1 for num in self._nums}
        # Note: Since nums can have duplicates, a simple count map per unique number is fragile.
        # The original logic handled duplicates by decrementing a count from a copy of the used stats.
        # Let's replicate the original logic more faithfully but cleaner.
        # Original logic:
        # 1. Count how many times each digit from the valid card set appears in the expression.
        # 2. For each card in self.nums, check if there is remaining usage allowance for that digit's string.
        # 3. Finally, check if all used digits are fully accounted for (all counts reached 0).

        # To strictly follow "Split Temporary Variable" and simplify:
        usage_counts = digit_usage.copy()

        for current_card in self._nums:
            card_str = str(current_card)
            if card_str in usage_counts and usage_counts[card_str] > 0:
                usage_counts[card_str] -= 1
            else:
                return False

        # Replace Temp with Query / Simplify
        return all(count == 0 for count in usage_counts.values())

    def evaluate_expression(self, expression):
        try:
            # Separate Query from Modifier: This method already returns a boolean, no side effects.
            # Inline Method logic: 
            result = (eval(expression) == TARGET_SCORE)
            return result
        except Exception:
            return DEFAULT_STATUS
